# ============================ توابع کمکی ============================

def set_rtl(p):
    pPr = p._p.get_or_add_pPr()
    pPr.append(OxmlElement("w:bidi"))

def style_run(run, size=FONT_SIZE, bold=False, font=None, rtl=True, color=None):
    font = font or FONT_NAME
    run.font.name = font
    run.font.size = Pt(size)
    run.font.bold = bold
    if color is not None:
        run.font.color.rgb = color
    rPr = run._element.get_or_add_rPr()
    rFonts = rPr.get_or_add_rFonts()
    rFonts.set(qn("w:cs"), font)
    rFonts.set(qn("w:eastAsia"), font)
    szCs = rPr.find(qn("w:szCs"))
    if szCs is None:
        szCs = OxmlElement("w:szCs")
        rPr.append(szCs)
    szCs.set(qn("w:val"), str(int(size * 2)))
    if bold:
        if rPr.find(qn("w:bCs")) is None:
            rPr.append(OxmlElement("w:bCs"))
    if rtl:
        if rPr.find(qn("w:rtl")) is None:
            rPr.append(OxmlElement("w:rtl"))

def add_para(doc, text, size=FONT_SIZE, bold=False, align="justify",
             space_after=8, line_spacing=1.5):
    p = doc.add_paragraph()
    set_rtl(p)
    if align == "justify":
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    elif align == "center":
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run(text)
    style_run(r, size=size, bold=bold)
    pf = p.paragraph_format
    pf.line_spacing = line_spacing
    pf.space_after = Pt(space_after)
    return p

def add_h(doc, text, level=1):
    p = doc.add_paragraph(style=f"Heading {level}")
    r = p.add_run(text)
    style_run(r, size=H1_SIZE if level == 1 else (H2_SIZE if level == 2 else H3_SIZE),
              bold=True, color=RGBColor(0, 0, 0))
    pf = p.paragraph_format
    pf.space_before = Pt(18 if level == 1 else (10 if level == 2 else 8))
    pf.space_after = Pt(8)
    pf.line_spacing = 1.3
    return p

def set_table_rtl(table):
    tblPr = table._tbl.tblPr
    tblPr.append(OxmlElement("w:bidiVisual"))

def fill_cell(cell, text, header=False):
    cell.vertical_alignment = WD_ALIGN_VERTICAL.CENTER
    p = cell.paragraphs[0]
    set_rtl(p)
    if header:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run(text)
    style_run(r, size=CAPTION_SIZE, bold=header)
    p.paragraph_format.space_before = Pt(2)
    p.paragraph_format.space_after = Pt(2)
    p.paragraph_format.line_spacing = 1.15
    if header:
        tcPr = cell._tc.get_or_add_tcPr()
        shd = OxmlElement("w:shd")
        shd.set(qn("w:val"), "clear")
        shd.set(qn("w:fill"), "E7EDF7")
        tcPr.append(shd)

def add_table(doc, headers, rows, widths=None):
    table = doc.add_table(rows=1, cols=len(headers))
    table.style = "Table Grid"
    table.alignment = WD_TABLE_ALIGNMENT.CENTER
    set_table_rtl(table)
    tblPr = table._tbl.tblPr
    layout = OxmlElement("w:tblLayout")
    layout.set(qn("w:type"), "fixed")
    tblPr.append(layout)
    for i, h in enumerate(headers):
        fill_cell(table.rows[0].cells[i], h, header=True)
    for row in rows:
        cells = table.add_row().cells
        for i, val in enumerate(row):
            fill_cell(cells[i], str(val))
    if widths:
        for i, w in enumerate(widths):
            for r_ in table.rows:
                if i < len(r_.cells):
                    r_.cells[i].width = Cm(w)
    return table

def add_caption(doc, text, kind="table"):
    style_name = "TableCaption" if kind == "table" else "FigureCaption"
    p = doc.add_paragraph(style=style_name)
    set_rtl(p)
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run(text)
    style_run(r, size=CAPTION_SIZE, bold=True)
    p.paragraph_format.space_before = Pt(6)
    p.paragraph_format.space_after = Pt(6)
    return p

def add_image(doc, path, caption, width_cm=15):
    p = doc.add_paragraph()
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run()
    run.add_picture(path, width=Cm(width_cm))
    p.paragraph_format.space_before = Pt(10)
    add_caption(doc, caption, kind="figure")

def add_toc_field(doc, instr, placeholder="برای به‌روزرسانی، کلید F9 را فشار دهید."):
    p = doc.add_paragraph()
    run = p.add_run()
    f1 = OxmlElement("w:fldChar"); f1.set(qn("w:fldCharType"), "begin")
    it = OxmlElement("w:instrText"); it.set(qn("xml:space"), "preserve")
    it.text = instr
    f2 = OxmlElement("w:fldChar"); f2.set(qn("w:fldCharType"), "separate")
    t = OxmlElement("w:t"); t.text = placeholder
    f3 = OxmlElement("w:fldChar"); f3.set(qn("w:fldCharType"), "end")
    for el in (f1, it, f2, t, f3):
        run._r.append(el)

def force_update_fields(doc):
    el = doc.settings.element
    upd = OxmlElement("w:updateFields")
    upd.set(qn("w:val"), "true")
    el.append(upd)

def setup_section(sec):
    sec.page_width = Cm(21)
    sec.page_height = Cm(29.7)
    sec.top_margin = Cm(2.5)
    sec.bottom_margin = Cm(2.5)
    sec.right_margin = Cm(3)
    sec.left_margin = Cm(2.5)

def add_footer_pagenum(section):
    footer = section.footer
    footer.is_linked_to_previous = False
    p = footer.paragraphs[0]
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = p.add_run()
    f1 = OxmlElement("w:fldChar"); f1.set(qn("w:fldCharType"), "begin")
    it = OxmlElement("w:instrText"); it.set(qn("xml:space"), "preserve"); it.text = "PAGE"
    f2 = OxmlElement("w:fldChar"); f2.set(qn("w:fldCharType"), "end")
    for el in (f1, it, f2):
        run._r.append(el)
    style_run(run, size=12, rtl=False)

def add_header_text(section, text):
    header = section.header
    header.is_linked_to_previous = False
    p = header.paragraphs[0]
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    r = p.add_run(text)
    style_run(r, size=11, rtl=False)

def setup_styles(doc):
    st = doc.styles["Normal"]
    st.font.name = FONT_NAME
    st.font.size = Pt(FONT_SIZE)
    rPr = st.element.get_or_add_rPr()
    rF = rPr.get_or_add_rFonts()
    rF.set(qn("w:cs"), FONT_NAME)
    for lvl, size in [(1, H1_SIZE), (2, H2_SIZE), (3, H3_SIZE)]:
        h = doc.styles[f"Heading {lvl}"]
        h.font.name = FONT_NAME
        h.font.size = Pt(size)
        h.font.bold = True
        h.font.color.rgb = RGBColor(0, 0, 0)
        hrPr = h.element.get_or_add_rPr()
        hF = hrPr.get_or_add_rFonts()
        hF.set(qn("w:cs"), FONT_NAME)
        szCs = OxmlElement("w:szCs"); szCs.set(qn("w:val"), str(size * 2)); hrPr.append(szCs)
        hrPr.append(OxmlElement("w:bCs"))
        hpPr = h.element.get_or_add_pPr()
        hpPr.append(OxmlElement("w:bidi"))
        if lvl == 1:
            hpPr.append(OxmlElement("w:pageBreakBefore"))
    for name in ("TableCaption", "FigureCaption"):
        try:
            cs = doc.styles.add_style(name, WD_STYLE_TYPE.PARAGRAPH)
        except ValueError:
            cs = doc.styles[name]
        cs.base_style = doc.styles["Normal"]
        cs.font.name = FONT_NAME
        cs.font.size = Pt(CAPTION_SIZE)
        cs.font.bold = True
        crPr = cs.element.get_or_add_rPr()
        crF = crPr.get_or_add_rFonts()
        crF.set(qn("w:cs"), FONT_NAME)
        sz = OxmlElement("w:szCs"); sz.set(qn("w:val"), str(CAPTION_SIZE * 2)); crPr.append(sz)
        crPr.append(OxmlElement("w:bCs"))
        cpPr = cs.element.get_or_add_pPr()
        cpPr.append(OxmlElement("w:bidi"))

