def find_files(keywords, exts=(".png", ".jpg", ".jpeg")):
    results = []
    try:
        for f in sorted(os.listdir(".")):
            low = f.lower()
            if low.endswith(exts) and any(k in low for k in keywords):
                results.append(f)
    except Exception:
        pass
    return results

