def build_front_matter(doc):
    # ---------- روی جلد ----------
    if LOGO:
        p = doc.add_paragraph()
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.space_after = Pt(30)
        p.add_run().add_picture(LOGO, width=Cm(4.5))
    add_para(doc, DEGREE_TEXT, size=16, bold=True, align="center", space_after=36)
    add_para(doc, "موضوع:", size=14, bold=True, align="center", space_after=4)
    add_para(doc, THESIS_TITLE, size=16, bold=True, align="center", space_after=10)
    add_para(doc, SUB_TITLE, size=14, bold=True, align="center", space_after=36)
    add_para(doc, "استاد راهنما:", size=14, bold=True, align="center", space_after=2)
    add_para(doc, PROFESSOR, size=14, align="center", space_after=20)
    add_para(doc, "نام دانشجو:", size=14, bold=True, align="center", space_after=2)
    add_para(doc, STUDENT_NAME, size=16, bold=True, align="center", space_after=40)
    add_para(doc, MONTH_YEAR, size=14, bold=True, align="center", space_after=0)
    doc.add_page_break()

    # ---------- صفحه عنوان ----------
    if LOGO:
        p = doc.add_paragraph()
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.space_after = Pt(30)
        p.add_run().add_picture(LOGO, width=Cm(4.5))
    add_para(doc, DEGREE_TEXT, size=16, bold=True, align="center", space_after=36)
    add_para(doc, "موضوع:", size=14, bold=True, align="center", space_after=4)
    add_para(doc, THESIS_TITLE, size=16, bold=True, align="center", space_after=10)
    add_para(doc, SUB_TITLE, size=14, bold=True, align="center", space_after=36)
    add_para(doc, "استاد راهنما:", size=14, bold=True, align="center", space_after=2)
    add_para(doc, PROFESSOR, size=14, align="center", space_after=20)
    add_para(doc, "استاد داور:", size=14, bold=True, align="center", space_after=2)
    add_para(doc, ".....................................", size=14, align="center", space_after=20)
    add_para(doc, "نام دانشجو:", size=14, bold=True, align="center", space_after=2)
    add_para(doc, STUDENT_NAME, size=16, bold=True, align="center", space_after=40)
    add_para(doc, MONTH_YEAR, size=14, bold=True, align="center", space_after=0)
    doc.add_page_break()

    # ---------- سپاسگزاری ----------
    add_h(doc, "سپاسگزاری", 1)
    add_para(doc, "فرمودند: حضرت علی (ع): «مَن عَلَّمَني حَرفاً فَقَد صَيَّرَني عَبداً»", size=15, bold=True)
    add_para(doc, "از تمامی اساتید، معلمان، استاد راهنما و خانواده در کل دوران تحصیل سپاسگزارم.")
    doc.add_page_break()

    # ---------- تقدیم ----------
    add_h(doc, "تقدیم به", 1)
    add_para(doc, "تمامی رهپویان راه علم و معرفت", size=15, bold=True, align="center")
    doc.add_page_break()

    # ---------- چکیده ----------
    add_h(doc, "چکیده", 1)
    add_para(doc, "هدف از این پروژه، توسعه و پیاده‌سازی وبسایت آزمایشگاه توانمندسازی نرم‌افزاری امنیت فضای تبادل اطلاعات (آفتا) با استفاده از فریم‌ورک لاراول است. این وبسایت، علاوه بر معرفی آزمایشگاه مذکور، شامل امکاناتی مانند تعریف پروژه‌ها، انتقال خبرها و مقالات توسط کاربران، انتقال چک‌لیست‌های آزمایشگاه، فرم‌های مخصوص آزمایشگاه و بخش‌های مرتبط با پنل کاربری است. در توسعه حاضر، ماژول‌های فروشگاه و خرید مقاله، پیشنهاد مقاله علمی، پایان‌نامه و رساله، مقالات بین‌المللی و صفحات علمی، درخواست مشاوره، لاگ‌های سیستمی پیشرفته، مسدودسازی IP و تنظیمات سایت به سیستم افزوده شده و ماژول‌های مقالات و تیکتینگ بهبودهای اساسی یافته‌اند. فریم‌ورک لاراول به دلیل داشتن سطح امنیتی بالا، ابزارها و پکیج‌های متنوع، ساختار منظم و مستندات کامل، برای این پروژه انتخاب شده و مفاهیمی مانند مدل‌ها، کنترلرها، روت‌ها و ویوها در قالب معماری MVC در آن به کار رفته است. در این توسعه، لایه سرویس لاگینگ جامع با بیش از سی متد و ثبت چهل‌ودو نوع رویداد، بهبودهای امنیتی شامل قفل حساب کاربری و مسدودسازی آدرس‌های IP و همچنین زیرساخت کامل فروشگاه محتوای علمی پیاده‌سازی شده است.")
    add_para(doc, "کلیدواژه‌ها: فریم‌ورک لاراول، توسعه وب، آزمایشگاه توانمندسازی نرم‌افزاری آفتا، امنیت فضای تبادل اطلاعات، فروشگاه اینترنتی، سیستم لاگینگ، مدیریت دسترسی", bold=True)
    doc.add_page_break()

    # ---------- فهرست‌ها ----------
    add_h(doc, "فهرست مطالب", 1)
    add_toc_field(doc, 'TOC \\o "1-2" \\h \\z \\u')
    doc.add_page_break()
    add_h(doc, "فهرست جداول", 1)
    add_toc_field(doc, 'TOC \\h \\z \\t "TableCaption,1"')
    doc.add_page_break()
    add_h(doc, "فهرست اشکال", 1)
    add_toc_field(doc, 'TOC \\h \\z \\t "FigureCaption,1"')
    doc.add_page_break()

    # ---------- علائم و اختصارات ----------
    add_h(doc, "لیست علائم و اختصارات", 1)
    abbrevs = [
        ("PHP (Hypertext Preprocessor)", "پیش‌پردازنده فرامتن"),
        ("MVC (Model-View-Controller)", "معماری مدل-ویو-کنترلر"),
        ("ORM (Object-Relational Mapper)", "نگاشت شیء به رابطه‌ای"),
        ("ERD (Entity Relationship Diagram)", "نمودار ارتباط موجودیت‌ها"),
        ("IP (Internet Protocol)", "پروتکل اینترنت"),
        ("HTTP (HyperText Transfer Protocol)", "پروتکل انتقال فرامتن"),
        ("URL (Uniform Resource Locator)", "نشانی یکتای دسترسی به منابع"),
        ("JSON (JavaScript Object Notation)", "قالب تبادل داده"),
        ("AJAX (Asynchronous JavaScript and XML)", "درخواست غیرهمگام"),
        ("UI/UX (User Interface / User Experience)", "رابط و تجربه کاربری"),
        ("API (Application Programming Interface)", "رابط برنامه‌نویسی کاربردی"),
        ("SQL (Structured Query Language)", "زبان پرس‌وجوی ساخت‌یافته"),
        ("IDE (Integrated Development Environment)", "محیط توسعه یکپارچه"),
        ("CTF (Capture The Flag)", "رویداد مسابقه امنیت سایبری"),
    ]
    for term, desc in abbrevs:
        add_para(doc, f"{term}: {desc}", space_after=4)

def build_body(doc):
    for item in BODY:
        kind = item[0]
        if kind == "h1":
            add_h(doc, item[1], 1)
        elif kind == "h2":
            add_h(doc, item[1], 2)
        elif kind == "h3":
            add_h(doc, item[1], 3)
        elif kind == "p":
            add_para(doc, item[1])
        elif kind == "tbl":
            data = item[1]
            add_caption(doc, data["caption"], kind="table")
            add_table(doc, data["headers"], data["rows"], data.get("widths"))
        elif kind == "img":
            _, path, caption = item
            if path and os.path.exists(path):
                add_image(doc, path, caption)
            else:
                add_para(doc, f"[در این قسمت تصویر «{caption}» درج شود — فایل تصویر یافت نشد]",
                         bold=True, align="center")

def main():
    doc = Document()
    setup_section(doc.sections[0])
    setup_styles(doc)

    # بخش جلد و صفحات آغازین (بدون شماره صفحه)
    build_front_matter(doc)

    # بخش اصلی با شماره صفحه و سرصفحه
    sec2 = doc.add_section(WD_SECTION.NEW_PAGE)
    setup_section(sec2)
    pg = OxmlElement("w:pgNumType")
    pg.set(qn("w:start"), "1")
    sec2._sectPr.append(pg)
    add_footer_pagenum(sec2)
    add_header_text(sec2, "توسعه وبسایت آزمایشگاه توانمندسازی نرم‌افزاری امنیت فضای تبادل اطلاعات (آفتا)")

    build_body(doc)

    force_update_fields(doc)
    doc.save(OUTPUT_FILE)

    # گزارش وضعیت
    print("=" * 60)
    print("فایل با موفقیت ساخته شد:", OUTPUT_FILE)
    print("نام دانشجو:", STUDENT_NAME)
    print("مقطع:", DEGREE_TEXT)
    print("تاریخ:", MONTH_YEAR)
    if LOGO:
        print("لوگوی دانشگاه:", LOGO)
    else:
        print("هشدار: لوگوی دانشگاه یافت نشد! فایلی با نام حاوی 'logo' یا 'لوگو' در پوشه بگذارید.")
    found = sum(1 for e in ERDS if e)
    print(f"تصاویر ERD پیدا شده: {found} از 3")
    if found < 3:
        print("هشدار: برای درج نمودارهای ERD، فایل‌های تصویری با نام حاوی 'ERD' در پوشه بگذارید.")
    print("پس از باز کردن فایل در Word، فهرست‌ها خودکار به‌روز می‌شوند (در صورت نیاز: Ctrl+A سپس F9)")
    print("=" * 60)

if __name__ == "__main__":
    main()
